async function fixture({checksReady=false}={}){const db=new PGlite();await db.exec(fs.readFileSync('tests/fixtures/maintenance-centre-base.sql','utf8'));await db.query("insert into auth.users values($1,'synthetic@example.test')",[uid]);await db.query("insert into account_access values($1,'Synthetic Office','admin','active')",[uid]);await db.query("insert into vehicles(id,vehicle_reg,vehicle_type,vehicle_name) values($1,'SYNTHETIC-1','FOUR_WHEEL_TRUCK','Synthetic truck')",[vid]);await db.query("insert into drivers(id,name,assigned_vehicle_id,vehicle_reg) values(1,'Synthetic Driver',$1,'SYNTHETIC-1')",[vid]);await db.exec(`alter table vehicles add column last_oil_change_date date,add column last_oil_change_odometer numeric,add column oil_change_interval_km numeric,add column created_at timestamptz default now(),add column updated_at timestamptz default now(),add column user_id uuid; alter table weekly_mileage add column vehicle_reg text,add column driver_id bigint,add column created_at timestamptz default now(),add column user_id uuid,add column is_odometer_baseline boolean default false;create table vehicle_service_logs(id uuid primary key default gen_random_uuid(),vehicle_id uuid,vehicle_reg text,service_type text,service_date date,odometer numeric,interval_km numeric,created_at timestamptz default now());create table oil_change_baselines(id uuid primary key default gen_random_uuid(),vehicle_reg text,last_oil_change_date date,last_odometer numeric,interval_km numeric,created_at timestamptz default now());create table oil_change_history(id uuid primary key,vehicle_reg text,oil_change_date date,odometer numeric,created_at timestamptz default now());grant select on vehicles,drivers,weekly_mileage,vehicle_service_logs,oil_change_baselines,oil_change_history to authenticated;`);
for(const name of ['20260914090000_add_maintenance.sql','20260923110000_maintenance_receipt_csv_import.sql','20261014100000_preventative_maintenance_centre.sql'])await db.exec(fs.readFileSync('supabase/migrations/'+name,'utf8'));
if(checksReady)await db.exec(fs.readFileSync('supabase/migrations/20261015100000_maintenance_checks_install.sql','utf8'));
const today=(await db.query("select (now() at time zone 'Asia/Bangkok')::date::text as today_key")).rows[0].today_key;await db.query("insert into weekly_mileage(vehicle_id,vehicle_reg,driver_id,week_ending,odometer_reading,mileage,user_id) values($1,'SYNTHETIC-1',1,$2,50000,50000,$3)",[vid,today,uid]);await db.query("insert into oil_change_baselines(vehicle_reg,last_oil_change_date,last_odometer,interval_km) values('SYNTHETIC-1','2026-01-01',35000,10000)");let queue=Promise.resolve();const bytes=new Map(),calls=[];
async function run(fn){const task=queue.then(async()=>{await db.exec('begin');try{await db.query("select set_config('request.jwt.claim.sub',$1,true)",[uid]);await db.exec('set local role authenticated');const r=await fn();await db.exec('commit');return r;}catch(e){await db.exec('rollback');throw e;}});queue=task.catch(()=>{});return task;}
const server=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');res.setHeader('Access-Control-Allow-Origin','*');res.setHeader('Access-Control-Allow-Headers','*');res.setHeader('Access-Control-Allow-Methods','GET,POST,DELETE,OPTIONS');res.setHeader('Content-Type','application/json');if(req.method==='OPTIONS'){res.end();return;}const chunks=[];for await(const b of req)chunks.push(b);const raw=Buffer.concat(chunks);let body={};try{body=JSON.parse(raw.toString()||'{}')}catch{}calls.push({path:url.pathname,method:req.method,body});
try{
 if(url.pathname==='/auth/v1/user'){res.end(JSON.stringify({id:uid,email:'synthetic@example.test',aud:'authenticated',role:'authenticated',app_metadata:{},user_metadata:{}}));return;}
 if(url.pathname.startsWith('/rest/v1/rpc/')){const name=url.pathname.split('/').pop();if(!['maintenance_vehicle_checks_version','save_maintenance_vehicle_checks','maintenance_centre_version','save_maintenance_record','delete_maintenance_record','save_vehicle_maintenance_schedule','save_maintenance_requirement'].includes(name)){res.end('[]');return;}const keys=Object.keys(body);const r=await run(()=>db.query('select '+name+'('+keys.map((k,i)=>{if(!/^[a-z_]+$/.test(k))throw Error('Bad key');return k+'=>$'+(i+1)}).join(',')+') result',keys.map(k=>body[k]!==null&&typeof body[k]==='object'?JSON.stringify(body[k]):body[k])));res.end(JSON.stringify(r.rows[0].result));return;}
 if(url.pathname.startsWith('/rest/v1/')){const table=url.pathname.split('/').pop();const allowed=['maintenance_vehicle_checks','vehicles','drivers','weekly_mileage','maintenance_records','maintenance_items','maintenance_requirements','maintenance_requirement_vehicles','maintenance_attachments','maintenance_audit','vehicle_service_logs','oil_change_baselines','oil_change_history'];if(!allowed.includes(table)){res.end('[]');return;}
 if(req.method==='POST'&&table==='maintenance_attachments'){const keys=Object.keys(body);const r=await run(()=>db.query(`insert into maintenance_attachments(${keys.join(',')}) values(${keys.map((_,i)=>'$'+(i+1)).join(',')}) returning *`,keys.map(k=>body[k])));res.end(JSON.stringify((req.headers.accept??'').includes('object+json')?r.rows[0]:r.rows));return;}
 const filters=[],params=[];for(const [k,val]of url.searchParams){if(!/^[a-z_]+$/.test(k)||!val.startsWith('eq.'))continue;params.push(val.slice(3));filters.push(k+'=$'+params.length);}
 const offset=Number(url.searchParams.get('offset')??0),limit=Number(url.searchParams.get('limit')??500);const select=url.searchParams.get('select')??'*';let result=await run(()=>db.query('select * from '+table+(filters.length?' where '+filters.join(' and '):'')+' limit '+limit+' offset '+offset,params));const dates=new Set(['check_date','week_ending','service_date','last_oil_change_date','oil_change_date','override_date']);const normalise=row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[k,dates.has(k)&&v!=null?(v instanceof Date?v.toISOString():String(v)).slice(0,10):v]));let rows=result.rows.map(normalise);
 if(table==='maintenance_items'&&select.includes('maintenance_records!inner')){const r=await run(()=>db.query('select * from maintenance_records'));rows=rows.map(i=>({...i,maintenance_records:{...normalise(r.rows.find(x=>x.id===i.record_id)),vehicles:{vehicle_reg:'SYNTHETIC-1'}}}));}
 if(table==='maintenance_requirements'&&select.includes('maintenance_requirement_vehicles')){const a=await run(()=>db.query('select * from maintenance_requirement_vehicles'));rows=rows.map(s=>({...s,maintenance_requirement_vehicles:a.rows.filter(x=>x.requirement_id===s.id)}));}
 if(table==='weekly_mileage')rows=rows.map(r=>({...r,driver:'Synthetic Driver'}));res.end(JSON.stringify((req.headers.accept??'').includes('object+json')?rows[0]??null:rows));return;}
 if(url.pathname.startsWith('/storage/v1/object/sign/')){const key=decodeURIComponent(url.pathname.replace('/storage/v1/object/sign/',''));if(req.method==='POST'){await run(()=>db.query('select * from storage.objects where bucket_id=$1 and name=$2',[key.split('/')[0],key.split('/').slice(1).join('/')]));res.end(JSON.stringify({signedURL:'/object/sign/'+key+'?token=synthetic'}));return;}res.setHeader('Content-Type','application/pdf');res.end(bytes.get(key));return;}
 if(url.pathname.startsWith('/storage/v1/object/')){const key=decodeURIComponent(url.pathname.replace('/storage/v1/object/',''));if(req.method==='POST'){await run(()=>db.query('insert into storage.objects(bucket_id,name) values($1,$2)',[key.split('/')[0],key.split('/').slice(1).join('/')]));bytes.set(key,raw);res.end(JSON.stringify({Key:key}));return;}}
 res.statusCode=404;res.end('{}');
}catch(e){res.statusCode=400;res.end(JSON.stringify({code:e.code,message:e.message}));}});
await new Promise(r=>server.listen(32125,'127.0.0.1',r));return {db,run,server,uid,vid,today,jwt,calls,bytes,async close(){server.closeAllConnections();await new Promise(r=>server.close(r));await db.close();}};}
